insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('elektrizitaetsweak-simmaring', 'Elektrizitätsweak Simmaring', '', '', '', '', 'Elektrizitätswerk Simmering', '[{"kategorie": "allg.", "text": "\"eines der landesweit bedeutendsten Heizkraftwerke im 11. Wiener Gemeindebezirk ([[Simmering]]), an der 1. [[Haidequerstraße]]\""}, {"kategorie": "", "text": "Der Bau wurde 1900 beschlossen und 1902 in Betrieb genommen. Es versorgte zunächst die Wiener Straßenbahnen und die öffentliche Beleuchtung mit Strom"}, {"kategorie": "", "text": "Das Kraftwerk wurde im Laufe der Jahre mehrmals erweitert und modernisiert, unter anderem mit Turbosätzen im Jahr 1906"}, {"kategorie": "", "text": "Während des [[Zweiten]] Weltkriegs erlitt das Werk schwere Zerstörungen, konnte aber bald wieder teilweise in Betrieb genommen werden. Es wurde stetig weiterentwickelt, wobei in den 1960er Jahren neue Kraftwerksblöcke errichtet wurden"}, {"kategorie": "", "text": "Das Kraftwerk deckt heute etwa 50 % des Strombedarfs der Stadt Wien und erzeugt auch Fernwärme. Es wird mit verschiedenen Energiequellen wie Erdgas, Heizöl und Biomasse betrieben und ist eines der wichtigsten Kraftwerke Österreichs"}, {"kategorie": "", "text": "Das Kraftwerk verfügt über eine Schwarzstartfähigkeit, das heißt, es kann sich nach einem Stromausfall selbst wieder in Betrieb setzen. Heute zählt es mit einem jährlichen Ausstoß von 817.246 Tonnen CO2 (2018) zu den größten Emittenten von Treibhausgasen in Österreich."}]'::jsonb, ''),
  ('kroftweak-simmaring', 'Kroftweak Simmaring', '', '', '', '', 'Kraftwerk Simmering', '[{"kategorie": "allg.", "text": "\"eines der landesweit bedeutendsten Heizkraftwerke im 11. Wiener Gemeindebezirk ([[Simmering]]), an der 1. [[Haidequerstraße]]\""}, {"kategorie": "", "text": "Der Bau wurde 1900 beschlossen und 1902 in Betrieb genommen. Es versorgte zunächst die Wiener Straßenbahnen und die öffentliche Beleuchtung mit Strom"}, {"kategorie": "", "text": "Das Kraftwerk wurde im Laufe der Jahre mehrmals erweitert und modernisiert, unter anderem mit Turbosätzen im Jahr 1906"}, {"kategorie": "", "text": "Während des [[Zweiten]] Weltkriegs erlitt das Werk schwere Zerstörungen, konnte aber bald wieder teilweise in Betrieb genommen werden. Es wurde stetig weiterentwickelt, wobei in den 1960er Jahren neue Kraftwerksblöcke errichtet wurden"}, {"kategorie": "", "text": "Das Kraftwerk deckt heute etwa 50 % des Strombedarfs der Stadt Wien und erzeugt auch Fernwärme. Es wird mit verschiedenen Energiequellen wie Erdgas, Heizöl und Biomasse betrieben und ist eines der wichtigsten Kraftwerke Österreichs"}, {"kategorie": "", "text": "Das Kraftwerk verfügt über eine Schwarzstartfähigkeit, das heißt, es kann sich nach einem Stromausfall selbst wieder in Betrieb setzen. Heute zählt es mit einem jährlichen Ausstoß von 817.246 Tonnen CO2 (2018) zu den größten Emittenten von Treibhausgasen in Österreich."}]'::jsonb, ''),
  ('simmaringa-kroftweak', 'Simmaringa Kroftweak', '', '', '', '', 'Simmeringer Kraftwerk', '[{"kategorie": "allg.", "text": "\"eines der landesweit bedeutendsten Heizkraftwerke im 11. Wiener Gemeindebezirk ([[Simmering]]), an der 1. [[Haidequerstraße]]\""}, {"kategorie": "", "text": "Der Bau wurde 1900 beschlossen und 1902 in Betrieb genommen. Es versorgte zunächst die Wiener Straßenbahnen und die öffentliche Beleuchtung mit Strom"}, {"kategorie": "", "text": "Das Kraftwerk wurde im Laufe der Jahre mehrmals erweitert und modernisiert, unter anderem mit Turbosätzen im Jahr 1906"}, {"kategorie": "", "text": "Während des [[Zweiten]] Weltkriegs erlitt das Werk schwere Zerstörungen, konnte aber bald wieder teilweise in Betrieb genommen werden. Es wurde stetig weiterentwickelt, wobei in den 1960er Jahren neue Kraftwerksblöcke errichtet wurden"}, {"kategorie": "", "text": "Das Kraftwerk deckt heute etwa 50 % des Strombedarfs der Stadt Wien und erzeugt auch Fernwärme. Es wird mit verschiedenen Energiequellen wie Erdgas, Heizöl und Biomasse betrieben und ist eines der wichtigsten Kraftwerke Österreichs"}, {"kategorie": "", "text": "Das Kraftwerk verfügt über eine Schwarzstartfähigkeit, das heißt, es kann sich nach einem Stromausfall selbst wieder in Betrieb setzen. Heute zählt es mit einem jährlichen Ausstoß von 817.246 Tonnen CO2 (2018) zu den größten Emittenten von Treibhausgasen in Österreich."}]'::jsonb, ''),
  ('simmaringa-laende', 'Simmaringa Lände', '', '', '', '', 'Simmeringer Lände', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsader im 11. Wiener Gemeindebezirk ([[Simmering]]), die entlang des rechten Ufers des [[Donaukanals]] verläuft\""}, {"kategorie": "", "text": "Sie wurde 1894 nach ihrer Lage direkt am Wasser benannt, da das Wort „Lände“ einen einfachen Landeplatz an einem Gewässer beschreibt, der im Wesentlichen die einfachste Form eines Binnenhafens darstellt"}, {"kategorie": "", "text": "Zuvor trug die Straße den Namen Donaukanallände, was ihren Bezug zum Donaukanal verdeutlichte"}, {"kategorie": "", "text": "In der Nähe der Simmeringer Lände befinden sich unter anderem das [[Elektrizitätswerk]] Simmering und andere industrielle Anlagen"}, {"kategorie": "", "text": "Heute ist die Simmeringer Lände eine wichtige Verkehrsader und hat gleichzeitig Bedeutung als Zubringer zum [[Wiener]] Hafen und zu den umliegenden Industriegebieten."}]'::jsonb, ''),
  ('schbittelaua-bruckn', 'Schbittelaua Bruckn', '', '', '', '', 'Spittelauer Brücke', '[{"kategorie": "allg.", "text": "Brückenkomplex in Wien, der den [[Donaukanal]] überquert und die Bezirke [[Döbling]] (19. Bezirk) und [[Brigittenau]] (20. Bezirk) miteinander verbindet"}, {"kategorie": "", "text": "Es handelt sich um eine multifunktionale Brücke, die sowohl für den Fahrzeugverkehr als auch für Fußgänger und Radfahrer genutzt wird. Zusätzlich ist die Brücke in die Infrastruktur der U-Bahn-Linie U6 integriert, die hier den Donaukanal ebenfalls überquert"}, {"kategorie": "", "text": "Die Spittelauer Brücke befindet sich in der Nähe der markanten [[Müllverbrennungsanlage]] Spittelau, einem Wahrzeichen von Wien, das von dem berühmten Künstler Friedensreich Hundertwasser gestaltet wurde. Weitere wichtige Gebäude in der Umgebung sind das [[Universitätszentrum]] Althanstraße, das [[Bundesamtsgebäude]] Josef-Holaubek-Platz und das Brigittenauer Bad. Diese Einrichtungen prägen das städtische Umfeld rund um die Brücke und machen sie zu einem wichtigen Verkehrsknotenpunkt im Norden Wiens"}, {"kategorie": "", "text": "Die Spittelauer Brücke ist eng mit der Entwicklung der städtischen Infrastruktur verbunden. Sie besteht aus mehreren Abschnitten, die im Rahmen von Verkehrsprojekten der Stadt Wien errichtet wurden. Der Geh- und Radweg der Spittelauer Brücke (Objektnummer 0905 3), die U6-Donaukanalbrücke und die Spittelauer Brücke B 227 (Objektnummer 0905 1) teilen sich weitgehend das gleiche Tragwerk, werden aber als eigenständige Brücken von der Wiener Magistratsabteilung MA 29 verwaltet"}, {"kategorie": "", "text": "Im Zuge der Erweiterung der U-Bahn-Linie U6 zwischen 1992 und 1995 wurde die ursprüngliche Abfahrtsrampe, die die Gürtelbrücke mit der [[Brigittenauer]] Lände (B 227) und weiter zur [[Nordbrücke]] verband, abgetragen. Der Grund dafür war der Bau eines massiven Tunnelportals, das den Verlauf der U6 unter die Erde führt. Als Teil dieser Bauarbeiten wurde die Spittelauer Brücke B 227 im Jahr 1992 errichtet, um eine neue Verbindung über den Donaukanal zu schaffen. Diese Brücke dient heute als wichtige Verkehrsader, die den [[Gürtel]] und die [[Brigittenauer]] Lände miteinander verbindet."}]'::jsonb, ''),
  ('fraunz-josefs-baun', 'Fraunz-Josefs-Baun', '', '', '', '', 'Franz-Josefs-Bahn', '[{"kategorie": "", "text": "Die Bahnstrecke wurde zu Ehren von Kaiser [[Franz]] Joseph I. benannt und sollte vor allem den Transport von Steinkohle aus dem Pilsner Becken nach Wien erleichtern"}, {"kategorie": "", "text": "Die Bauarbeiten begannen 1866, und bis 1870 war die 455 Kilometer lange Strecke von Eger (Cheb) bis Wien fertiggestellt. Die Strecke schloss im Norden an die Franz-Josefs-Bahn in Böhmen und im Süden an das Wiener Schienennetz an"}, {"kategorie": "", "text": "Der [[Franz-Josefs-Bahnhof]] in Wien wurde am 4. Juni 1872 eröffnet, und die Bahn verband unter anderem Städte wie Gmünd, Budweis, und Prag. Die Bahn diente sowohl dem Wirtschaftsverkehr als auch dem Tourismus, da sie den Zugang zu den Kurorten Karlsbad (Karlovy Vary) und Marienbad (Mariánské Lázně) erleichterte"}, {"kategorie": "", "text": "Nach 1918 verlor die Bahn nach der Grenzziehung zwischen Österreich und der Tschechoslowakei an Bedeutung. Der Bahnknoten České Velenice wurde der Tschechoslowakei zugeschlagen, und der Verkehr auf der Franz-Josefs-Bahn ging stark zurück, insbesondere während des Kalten Krieges"}, {"kategorie": "", "text": "Die Franz-Josefs-Bahn verbindet heute Wien über Tulln an der Donau, das Weinviertel und das Waldviertel mit Gmünd. Historisch gesehen war die Strecke eine wichtige Verbindung zwischen Österreich und Böhmen und wurde zu einer Hauptbahn für den Transport von landwirtschaftlichen und industriellen Gütern nach Wien"}, {"kategorie": "", "text": "In den 1990er Jahren wurde die Strecke bis zur österreichisch-tschechischen Grenze elektrifiziert. Während die Strecke früher für internationale Verbindungen, wie den berühmten [[Vindobona-Express]], genutzt wurde, hat sie heute überwiegend regionale Bedeutung. Seit Dezember 2022 gibt es jedoch wieder einige durchgehende Züge zwischen Wien und Prag über die Franz-Josefs-Bahn"}, {"kategorie": "", "text": "Laut Plänen der Europäischen Union soll die Franz-Josefs-Bahn bis 2030 modernisiert und für den internationalen Verkehr aufgewertet werden. Die Modernisierung soll die Strecke schneller und effizienter machen, um wieder eine wichtige internationale Verbindung zu schaffen."}]'::jsonb, ''),
  ('k-u-k-hofsalonzug', 'k.u.k. Hofsalonzug', '', '', '', '', 'k.u.k. Hofsalonzug', '[{"kategorie": "allg.", "text": "\"luxuriöser Eisenbahnzug der [[Habsburger]] Monarchie, der von den Monarchen [[Franz]] Joseph I. und später [[Karl]] I. für Reisen im In- und Ausland genutzt wurde (auch als \"kaiserlicher Hofzug\" oder \"Kaiserzug\" bezeichnet)\""}, {"kategorie": "", "text": "Der Zug wurde 1891 im Auftrag der österreichischen Bahnverwaltungen durch die k.k. Generaldirektion der österreichischen Eisenbahnen in Auftrag gegeben und von der Waggonfabrik Ringhoffer in Prag gebaut"}, {"kategorie": "", "text": "Dieser Hofzug diente offiziellen Reisen des Kaisers und enthielt luxuriös ausgestattete Salonwagen, Schlaf- und Speisewagen sowie Abteile für die kaiserliche Familie und deren Gefolge"}, {"kategorie": "", "text": "Der Zug von 1891 war der erste einheitliche Hofzug, der speziell für den Kaiser und seinen Hofstaat gebaut wurde. Er bestand aus acht Wagen mit luxuriösen Interieurs, darunter ein Salonwagen für den Kaiser, ein Speisewagen und ein Küchenwagen. Die Innenausstattung war prunkvoll, im Makart-Stil gehalten, mit Samtvorhängen, edlen Hölzern und goldenen Verzierungen"}, {"kategorie": "", "text": "Mit dem Ende der Habsburgermonarchie 1918 und dem Abdanken von Kaiser Karl I. wurde der Hofsalonzug aufgelöst. Einige der Waggons wurden von den Nachfolgestaaten übernommen, andere wurden verkauft oder in Museen ausgestellt"}, {"kategorie": "", "text": "Der außen sehr schlichte, 1873 gebaute Hofsalonwagen Hz 011 von Kaiserin Elisabeth ist im Wiener [[Technischen]] Museum ausgestellt. Über eine seitliche Galerie kann man durch die Fenster in das prunkvolle Innere des Wagens blicken."}]'::jsonb, ''),
  ('vindobona-express', 'Vindobona-Express', '', '', '', '', 'Vindobona-Express', '[{"kategorie": "allg.", "text": "\"internationaler Zug, der ursprünglich von 1957 bis 2014 und wieder seit Juni 2020 verkehrt\""}, {"kategorie": "", "text": "Der Name \"Vindobona\" leitet sich von der lateinischen Bezeichnung für die [[Stadt]] Wien ab. Der Zug verbindet wichtige Städte wie Berlin, Prag, und Wien und diente als bedeutende internationale Verbindung zwischen diesen Metropolen"}, {"kategorie": "", "text": "1957–1990: Der Vindobona wurde erstmals 1957 als Schnelltriebwagen zwischen Berlin und Wien eingeführt, wobei er über Dresden und Prag fuhr. Die Strecke wurde insbesondere von Diplomaten und Transitreisenden genutzt"}, {"kategorie": "", "text": "1990–2014: Nach den politischen Veränderungen in Osteuropa wurde der Zug zum EuroCity aufgewertet. Ab 2001 wurde der Laufweg nach Hamburg verlängert. Zwischen 2009 und 2014 wurde der Vindobona sogar bis Villach geführt, bevor der Betrieb im Jahr 2014 eingestellt wurde"}, {"kategorie": "", "text": "Wiederaufnahme ab 2020: Seit Juni 2020 verkehrt der Zug wieder zwischen Berlin, Prag, und Wien, mit einem Abstecher bis nach Graz. Er wird unter dem Namen \"Vindobona\" in Deutschland, Tschechien, und Österreich betrieben und verbindet die Städte im komfortablen Railjet-Stil"}, {"kategorie": "", "text": "Der Vindobona soll weiterhin eine bedeutende Rolle im internationalen Bahnverkehr spielen. Ab 2023 wird ein Ausbau der Strecke zwischen České Velenice und Prag erwartet, der die Fahrzeit weiter verkürzen soll. Es gibt Pläne, den Zug auch wieder über die klassische Strecke der [[Franz-Josefs-Bahn]] zu führen."}]'::jsonb, ''),
  ('universitaetszentrum-althangrund', 'Universitätszentrum Althangrund', '', '', '', '', 'Universitätszentrum Althangrund', '[{"kategorie": "", "text": "Der Komplex wurde vorwiegend als Überdeckelung der [[Franz-Josefs-Bahn]] und des Frachtenbahnhofs errichtet und beherbergt zahlreiche Einrichtungen der Universität Wien. Bis September 2013 befand sich dort auch die [[Wirtschaftsuniversität]] Wien (WU)"}, {"kategorie": "", "text": "Das UZA liegt im Stadtteil [[Althangrund]] und grenzt im Westen an die [[Augasse]] und den [[Liechtenwerder]] Platz, im Norden und Osten an die [[Nordbergbrücke]] und den [[Josef-Holaubek-Platz]]"}, {"kategorie": "", "text": "Es befindet sich in der Nähe von wichtigen Einrichtungen wie dem [[Bundesamtsgebäude]] Josef-Holaubek-Platz und der bekannten [[Hundertwasser-Müllverbrennungsanlage]] Spittelau"}, {"kategorie": "", "text": "Mit dem Umzug der Wirtschaftsuniversität Wien und Teilen der Universität Wien wurden viele Gebäude des UZA umgenutzt. Seit 2017 nutzt etwa das Arbeits- und Sozialgericht Wien Teile des UZA 3. Weitere Teile werden von der Universität für Bodenkultur Wien und der Akademie der bildenden Künste genutzt."}]'::jsonb, ''),
  ('liichtnweada-plotz', 'Liichtnweada Plotz', '', '', '', '', 'Liechtenwerder Platz', '[{"kategorie": "allg.", "text": "belebter Platz an der Grenze des 9. und 19. Wiener Gemeindebezirks ([[Alsergrund]] und [[Döbling]]), der am 20. Dezember 1904 nach der ehemaligen Donauinsel Liechtenwerder benannt wurde"}, {"kategorie": "", "text": "Diese Insel war im 13. Jahrhundert eine wiesenreiche Flusslandschaft und wurde bereits im Jahr 1280 unter dem Namen \"Alt-Lichtenwörd\" erwähnt"}, {"kategorie": "", "text": "Der Liechtenwerder Platz markiert heute die westliche Begrenzung des Stadtteils Althangrund im 9. Bezirk"}, {"kategorie": "", "text": "Sein Name verweist bis heute auf die historischen, naturnahen Fluss- und Wiesenlandschaften entlang der Donau in diesem Gebiet."}]'::jsonb, ''),
  ('bertha-zuckerkandl-weg', 'Bertha-Zuckerkandl-Weg', '', '', '', '', 'Bertha-Zuckerkandl-Weg', '[{"kategorie": "allg.", "text": "\"Fuß- und Radweg, der auf einem stillgelegten Teilstück des ehemaligen [[Verbindungsbogens]] (alte Nordbergbrücke) verläuft\""}, {"kategorie": "", "text": "Er wurde am 2. Juni 2009 nach der Journalistin, Schriftstellerin, Übersetzerin und Salonnière Bertha Zuckerkandl (1864–1945) benannt, einer bedeutenden Persönlichkeit der Wiener Kunst- und Kulturszene des frühen 20. Jahrhunderts"}, {"kategorie": "", "text": "Bertha Zuckerkandl wuchs in einer intellektuellen, kunstsinnigen Familie auf, deren Salon Treffpunkt von Künstlern, Schriftstellern und Wissenschaftlern war. Ihr eigener Salon in Wien wurde später zu einem wichtigen Zentrum der Wiener Avantgarde, in dem Persönlichkeiten wie Gustav Klimt, Arthur Schnitzler und Max Reinhardt verkehrten. Sie förderte insbesondere die [[Wiener]] Werkstätte und die Secessionisten und trug wesentlich zur Förderung der modernen Kunst und Kultur in Wien bei"}, {"kategorie": "", "text": "Der Bertha-Zuckerkandl-Weg symbolisiert heute die Erinnerung an ihre kulturellen Verdienste"}, {"kategorie": "", "text": "Ein Teil des Weges war zuvor ein Abschnitt der [[Wiener]] Stadtbahn, die den [[Verbindungsbogen]] zwischen der Gürtellinie und der Donaukanallinie bildete"}, {"kategorie": "", "text": "Ein 300 Meter langes Teilstück des Verbindungsbogens blieb jedoch erhalten und wird bis heute von der U6 befahren"}, {"kategorie": "", "text": "Der stillgelegte Rest der Strecke wurde unter dem Namen [[Bertha-Zuckerkandl-Weg]] als Fuß- und Radweg umgewidmet. Ein einzelner Bogen der Strecke wurde abgerissen, während der Großteil der alten Viaduktbögen noch besteht."}]'::jsonb, ''),
  ('wiina-weakstaettn', 'Wiina Weakstättn', '', '', '', '', 'Wiener Werkstätte', '[{"kategorie": "allg.", "text": "\"historische Produktionsgemeinschaft bildender Künstler, die 1903 in Wien von Josef Hoffmann, Koloman Moser und dem Textilfabrikanten und Mäzen Fritz Waerndorfer gegründet wurde\""}, {"kategorie": "", "text": "Ihr Ziel war es, der industriellen Massenproduktion und dem Historismus durch handwerklich hochwertige und künstlerisch anspruchsvolle Produkte entgegenzuwirken, ähnlich wie die britische Arts and Crafts-Bewegung"}, {"kategorie": "", "text": "Das Design der Wiener Werkstätte zeichnete sich durch eine schrittweise Entwicklung vom floralen Jugendstil hin zu geometrisch-abstrakten Formen aus. Sie war stark mit der [[Wiener]] Secession und der [[Kunstgewerbeschule]] verbunden und galt als bedeutender Vorreiter des modernen Kunstgewerbes"}, {"kategorie": "", "text": "Die Wiener Werkstätte erfreute sich insbesondere zu Beginn großer Erfolge und expandierte international, mit Verkaufsstellen in Städten wie Berlin, Zürich und New York. Eines ihrer bekanntesten Werke war die Ausstattung des Palais Stoclet in Brüssel, das als Gesamtkunstwerk von Hoffmann entworfen und von der Wiener Werkstätte ausgeführt wurde"}, {"kategorie": "", "text": "Trotz ihres künstlerischen Erfolges geriet die Wiener Werkstätte aufgrund finanzieller Schwierigkeiten, verschärft durch die Weltwirtschaftskrise, in Bedrängnis und musste 1932 schließlich liquidiert werden."}]'::jsonb, ''),
  ('wiina-kunstgeweabeschui', 'Wiina Kunstgeweabeschui', '', '', '', '', 'Wiener Kunstgewerbeschule', '[{"kategorie": "", "text": "Die Kunstgewerbeschule wurde am 27. September 1867 auf Initiative von Kaiser [[Franz]] Joseph I. gegründet und eröffnete am 1. Oktober 1868 als „Oberste Schule für das Kunstgewerbe“. Ihr ursprünglicher Standort war im Palais Brenner in Wien, bevor sie 1872 in das neu errichtete Gebäude des Österreichischen Museums für Kunst und Industrie (heute [[MAK]] – Museum für angewandte Kunst) am Stubenring übersiedelte"}, {"kategorie": "", "text": "Die Kunstgewerbeschule hatte das Ziel, Künstler und Handwerker in den angewandten Künsten auszubilden und die künstlerische Gestaltung von Gebrauchsgegenständen zu fördern. Sie war stark mit der britischen Arts and Crafts-Bewegung verwandt und setzte auf handwerkliche Qualität sowie künstlerische Innovation"}, {"kategorie": "", "text": "Die Schule spielte eine zentrale Rolle in der Entwicklung des [[Wiener]] Jugendstils und des modernen Designs und war eng mit der [[Wiener]] Secession und der [[Wiener]] Werkstätte verbunden. Bekannte Künstler wie Koloman Moser, Josef Hoffmann und Gustav Klimt lehrten oder studierten hier"}, {"kategorie": "", "text": "Im Jahr 1999 ging aus der Kunstgewerbeschule die Universität für angewandte Kunst Wien hervor. Das [[MAK]], das Österreichische Museum für angewandte Kunst, besteht weiterhin unabhängig und setzt sich mit der Geschichte und den Werken der angewandten Kunst auseinander."}]'::jsonb, ''),
  ('josef-holaubek-plotz', 'Josef-Holaubek-Plotz', '', '', '', '', 'Josef-Holaubek-Platz', '[{"kategorie": "allg.", "text": "\"bedeutender Verwaltungsplatz im 9. Wiener Gemeindebezirk ([[Alsergrund]]), welcher sich direkt neben dem Bundesamtsgebäude der Bundespolizeidirektion Wien befindet\""}, {"kategorie": "", "text": "Der Platz ist nach dem ehemaligen Wiener Polizeipräsidenten Josef Holaubek benannt (*5. Jänner 1907, †10. Februar 1999)"}, {"kategorie": "", "text": "Josef Holaubek war ursprünglich ausgebildeter Tischler und trat 1928 in den Dienst der städtischen Feuerwehr. Aufgrund seiner sozialdemokratischen Gesinnung wurde er während des [[Ständestaats]] und unter den Nationalsozialisten politisch verfolgt und inhaftiert"}, {"kategorie": "", "text": "Nach dem Ende des [[Zweiten]] Weltkriegs gelang ihm als Branddirektor der Stadt Wien die Wiederherstellung eines funktionierenden Brandschutzes in Wien. 1947 wurde Holaubek zum Polizeipräsidenten von Wien ernannt, eine Rolle, in der er besonders für seine Führungsstärke während der Besatzungszeit und beim Aufbau der Polizei bekannt wurde"}, {"kategorie": "", "text": "Berühmt wurde Holaubek durch eine Geiselnahme 1971, als er unbewaffnet mit dem bewaffneten Geiselnehmer Walter Schubirsch verhandelte und ihn mit den Worten „I bin’s, der Präsident“ zur Aufgabe bewegte. Dieses Ereignis prägte nachhaltig sein öffentliches Bild als besonnener und mutiger Polizeipräsident"}, {"kategorie": "", "text": "Der Josef-Holaubek-Platz ist vor allem als Vorplatz für das Bundesamtsgebäude der Bundespolizeidirektion Wien bekannt ([[Bundesamtsgebäude]] Josef-Holaubek-Platz), wodurch er eine zentrale Funktion für die öffentliche Verwaltung und Sicherheit der Stadt einnimmt;  7.Er liegt auch in der Nähe zu weiteren wichtigen städtischen Einrichtungen wie dem [[Universitätszentrum]] Althangrund oder der [[Müllverbrennungsanlage]] Spittelau."}]'::jsonb, ''),
  ('bundesaumtsgebeide-josef-holaubek-plotz', 'Bundesaumtsgebeide Josef-Holaubek-Plotz', '', '', '', '', 'Bundesamtsgebäude Josef-Holaubek-Platz', '[{"kategorie": "allg.", "text": "\"großer Verwaltungs- und Dienstgebäudekomplex im 9. Wiener Gemeindebezirk ([[Alsergrund]]), am [[Josef-Holaubek-Platz]]\""}, {"kategorie": "", "text": "Das Bundesamtsgebäude beherbergt wichtige Dienststellen der Landespolizeidirektion Wien sowie das Bundeskriminalamt und spielt somit eine zentrale Rolle in der Verwaltung und Sicherheitsstruktur der Stadt"}, {"kategorie": "", "text": "Das Gebäude wurde als Teil der Überbauung der Gleisanlagen des [[Franz-Josefs-Bahnhofs]] errichtet. Die Bauarbeiten begannen zwischen 1980 und 1983 mit der Basiskonstruktion, und 1986 wurde der eigentliche Grundstein gelegt"}, {"kategorie": "", "text": "Das Gebäude ist nach dem ehemaligen langjährigen Polizeipräsidenten Josef Holaubek benannt, der 25 Jahre in dieser Position wirkte. Zuvor war das Gebäude als Bundesamtsgebäude [[Liechtenwerder Platz]] bekannt, bevor der Platz 2000 zu Ehren Holaubeks umbenannt wurde."}]'::jsonb, ''),
  ('bundesaumtsgebeide-eadbeag', 'Bundesaumtsgebeide Eadbeag', '', '', '', '', 'Bundesamtsgebäude Erdberg', '[{"kategorie": "allg.", "text": "\"wichtiger Verwaltungs- und Dienstgebäudekomplex im 3. Wiener Gemeindebezirk ([[Landstraße]]), im Stadtteil [[Erdberg]] an der [[Erdbergstraße]] 192–196\""}, {"kategorie": "", "text": "Es beherbergt unter anderem das [[Österreichische]] Staatsarchiv, das Bundesverwaltungsgericht sowie das Wiener Ballsportgymnasium. Der Gebäudekomplex ist architektonisch durch seine markante achteckige Form bekannt, weshalb es auch den Spitznamen \"Oktoneum\" trägt"}, {"kategorie": "", "text": "Das Gebäude, das zwischen 1980 und 1986 nach Plänen des Architekten Peter Czernin errichtet wurde, zeichnet sich durch drei ringförmige Achtecke (Oktogone) aus, die sowohl in der äußeren Form als auch in der Struktur der Obergeschosse zu finden sind. Diese Achtecke stehen symbolisch für acht zentrale Begriffe: Tradition, Ästhetik, Funktion, Engagement, Monumentalität, Technologie, Innovation und Ökonomie"}, {"kategorie": "", "text": "Der Bau wurde 1986 abgeschlossen. Anfangs beherbergte das Gebäude unter anderem die Bundeszoll- und Zollwachschule, die bis zur Auflösung der Zollwache 1995 im nördlichen Teil des Komplexes untergebracht war. Danach wurde der Standort von der Bundespolizei sowie der Bundesfinanzakademie genutzt"}, {"kategorie": "", "text": "Ein Teil der Räumlichkeiten war zwischenzeitlich auch als Studentenheim vorgesehen, jedoch wurden die Zimmer im Jahr 2014 kurzfristig als Notquartier für Flüchtlinge verwendet. Anfang 2015 zogen die letzten Flüchtlinge aus, und die Räume wurden wieder anderweitig genutzt"}, {"kategorie": "", "text": "Heute befinden sich im Bundesamtsgebäude Erdberg neben dem Österreichischen Staatsarchiv und dem Bundesverwaltungsgericht auch weitere Behörden sowie Bildungs- und Verwaltungseinrichtungen."}]'::jsonb, ''),
  ('wiina-frochtnbaunhof', 'Wiina Frochtnbaunhof', '', '', '', '', 'Wiener Frachtenbahnhof', '[{"kategorie": "allg.", "text": "\"ehemals bedeutende logistische Drehscheibe und ein zentrales Element der Infrastruktur im 10. Wiener Gemeindebezirk ([[Favoriten]]), das lange Zeit eine besondere Stellung in der Stadt innehatte\""}, {"kategorie": "", "text": "Der Frachtenbahnhof befand sich auf einem weitläufigen Areal, das nach dem [[Zweiten]] Weltkrieg bis zu seinem Abbruch als „No-go-Zone“ galt, da es durch eine hohe Mauer vom restlichen Stadtgebiet abgeschottet war"}, {"kategorie": "", "text": "Diese Mauer, die ursprünglich dazu gedacht war, das Bahngelände vor unbefugtem Betreten zu schützen, prägte die Umgebung stark. Viele Anwohner und insbesondere Kinder und Jugendliche entwickelten im Laufe der Zeit eine Faszination für diesen abgeschiedenen und teilweise gefährlichen Ort"}, {"kategorie": "", "text": "Für die Kinder der umliegenden Viertel war der Frachtenbahnhof ein Abenteuerspielplatz, trotz seiner Gefahren. Sie schlichen sich durch Lücken in der Mauer, erkundeten die Lagerhallen und sammelten die Kohlen, die von den Güterzügen gefallen waren"}, {"kategorie": "", "text": "Für die Erwachsenen war der Frachtenbahnhof ebenfalls ein Ort, der trotz seiner offiziellen Nutzung oft auf halblegalen Wegen durchquert wurde, um Zeit zu sparen. So nutzten sie geheime Pfade, die von den Portieren mit einem Augenzwinkern geduldet wurden, um schneller in benachbarte Viertel wie den Schweizergarten oder zum Südbahnhof zu gelangen"}, {"kategorie": "", "text": "Der Frachtenbahnhof war auch ein Ort, der von illegalen Aktivitäten durchzogen war. Mit der Zeit verfielen Teile des Geländes, und das Postgebäude etwa wurde nach seiner Stilllegung von Gruppen genutzt, die das Bauwerk als Quelle für Rohstoffe, insbesondere Kupfer, plünderten. Diese kriminellen Aktivitäten waren schwer zu kontrollieren, da das Gelände so weitläufig und unübersichtlich war"}, {"kategorie": "", "text": "Darüber hinaus war der Frachtenbahnhof ein sozialer Treffpunkt für viele Anwohner, insbesondere dank des legendären Gasthauses „Zum Kamptaler“, das mitten in dieser sonst unzugänglichen und industriellen Gegend eine schattige Oase bot. Viele Treffen und Besprechungen endeten dort, und das Lokal war über die Jahrzehnte ein fester Bestandteil des Lebens rund um den Frachtenbahnhof"}, {"kategorie": "", "text": "Obwohl der Frachtenbahnhof schließlich abgerissen wurde, um Platz für das moderne [[Sonnwendviertel]], das [[Quartier]] Belvedere und den neuen [[Wiener]] Hauptbahnhof zu machen, blieb die Erinnerung an dasLokal  „Kamptaler“ erhalten, das heute unter neuem Namen weitergeführt wird."}]'::jsonb, ''),
  ('wiina-vabindungsbaun', 'Wiina Vabindungsbaun', '', '', '', '', 'Wiener Verbindungsbahn', '[{"kategorie": "allg.", "text": "\"Bezeichnung für mehrere Bahnstrecken in Wien, die in unterschiedlichen Zeitperioden errichtet wurden, um die Hauptbahnhöfe und Güterbahnhöfe der Stadt miteinander zu verbinden\""}, {"kategorie": "", "text": "Sie dienten sowohl dem Personen- als auch dem Güterverkehr und waren von großer strategischer Bedeutung, insbesondere auch für das Militär und die Industrie"}, {"kategorie": "", "text": "Erste Verbindungsbahn (1851 vollendet): Diese Strecke führte vom [[Nordbahnhof]] beim [[Praterstern]] über den [[Donaukanal]] zum [[Südbahnhof]] (heute [[Hauptbahnhof]]). Heute ist sie ein stark frequentierter Teil der Wiener [[S-Bahn-Stammstrecke]], die [[Floridsdorf]] über den [[Praterstern]] mit [[Meidling]] verbindet"}, {"kategorie": "", "text": "Zweite Verbindungsbahn: Diese Strecke verbindet den [[Westbahnhof]] über [[Penzing]], [[Speising]] und [[Hetzendorf]] mit der [[Südbahn]] und der [[Donauländebahn]]"}, {"kategorie": "", "text": "Dritte Verbindungsbahn ([[Donauländebahn]]): Diese Güterbahnstrecke führt von [[Meidling]] über [[Hetzendorf]] an das rechte Ufer der regulierten Donau, wo sie in die [[Donauuferbahn]] mündet. Sie verbindet diverse Strecken der [[Südbahn]], [[Ostbahn]] und [[Pottendorfer]] Linie"}, {"kategorie": "", "text": "Floridsdorfer Hochbahn (Italienerschleife): Diese während des [[Ersten]] Weltkriegs errichtete Verbindung zwischen Nordwestbahn und Nordbahn war von strategischer Bedeutung und wurde nach Jahrzehnten des Stillstands wieder in Betrieb genommen"}, {"kategorie": "", "text": "Vorortelinie: Diese verbindet die [[Westbahn]] mit der [[Franz-Josefs-Bahn]] und bietet seit 1987 wieder Personenverkehr als [[S-Bahn-Linie]] S45"}, {"kategorie": "", "text": "Die verschiedenen Verbindungsbahnen hatten ursprünglich auch strategische Bedeutung für das k.u.k. Militär und spielten im Güterverkehr eine große Rolle, da sie Umschlagplätze und Industriegleise miteinander verbanden."}]'::jsonb, ''),
  ('wiina-flughoofn', 'Wiina Flughoofn', '', '', '', '', 'Wiener Flughafen', '[{"kategorie": "", "text": "Ursprünglich 1938 als Militärflugplatz gegründet, entwickelte er sich nach dem [[Zweiten]] Weltkrieg zu einem bedeutenden zivilen Flughafen und Verkehrsknotenpunkt. Er wird von der börsennotierten Flughafen Wien AG betrieben und ist ein wichtiges Drehkreuz für Flüge nach Osteuropa, den Nahen Osten, sowie auf Langstreckenverbindungen"}, {"kategorie": "", "text": "Der Flughafen erstreckt sich über rund 10 Quadratkilometer und verfügt über zwei Start- und Landebahnen: Piste 11/29 (3.500 m) und Piste 16/34 (3.600 m). Eine dritte Piste ist in Planung, denn seit der Eröffnung hat sich das Passagieraufkommen stark entwickelt (mit einem Höchststand von nunmehr über 30 Millionen Passagieren)"}, {"kategorie": "", "text": "Historisch spielte der Flughafen eine wichtige Rolle als KZ-Außenlager während des [[Zweiten]] Weltkriegs, wo Zwangsarbeiter für die Produktion von Heinkel-Flugzeugen eingesetzt wurden. Nach dem Krieg wurde er von den britischen Besatzungstruppen als RAF-Station genutzt, bevor er 1954 in zivile Nutzung überging."}]'::jsonb, ''),
  ('zentraeuvaschubbaunhof-wiin-kledering', 'Zenträuvaschubbaunhof Wiin-Kledering', '', '', '', '', 'Zentralverschiebebahnhof Wien-Kledering', '[{"kategorie": "allg.", "text": "\"größter Verschiebebahnhof Österreichs, der eine zentrale Rolle im Güterverkehr der [[Österreichischen]] Bundesbahnen (ÖBB) spielt\""}, {"kategorie": "", "text": "Er befindet sich an der südöstlichen Grenze Wiens im 10. Bezirk ([[Favoriten]]) und erstreckt sich teilweise auf das Gebiet der Stadt Schwechat. Schienenseitig liegt er entlang der [[Ostbahn]] zwischen dem [[Wiener]] Hauptbahnhof und Bruck an der Leitha"}, {"kategorie": "", "text": "Um den Wiener Güterverkehr effizienter zu gestalten, wurde beschlossen, die bisher auf mehrere Bahnhöfe verteilte Zugbildung in einem Großverschiebebahnhof zu zentralisieren. Der Bau begann 1978, und nach mehreren Hochfahrphasen wurde der Bahnhof 1987 vollständig in Betrieb genommen. Die Baukosten beliefen sich auf 3,8 Milliarden Schilling"}, {"kategorie": "", "text": "Der Bahnhof hat eine Kapazität von 6.100 Wagen pro Tag, die über eine Gleisanlage von 120 Kilometern Länge verteilt sind. Der Bahnhof besteht aus einer 15-gleisigen Einfahrgruppe, einer 48-gleisigen Richtungsgruppe, in der die Güterwagen nach Zielbahnhöfen sortiert werden, und einer 10-gleisigen Ausfahrgruppe"}, {"kategorie": "", "text": "Der Hauptabrollberg ermöglicht die Zugzerlegung mit einer Kapazität von bis zu 300 Wagen pro Stunde. Für die Steuerung der Rangierprozesse kommen teilweise funkferngesteuerte Lokomotiven und computergesteuerte Bremssysteme zum Einsatz"}, {"kategorie": "", "text": "Der Zentralverschiebebahnhof Wien-Kledering dient ausschließlich dem Güterverkehr und konzentriert sich auf die Zerlegung und Neugestaltung von Güterzügen. Es gibt keine Umschlagsanlagen, da der eigentliche Warenumschlag an anderen Standorten wie am [[Güterterminal]] Wien-Inzersdorf oder [[Freudenau]] erfolgt"}, {"kategorie": "", "text": "Der Bahnhof entlastet durch seine Größe und Kapazität andere Verschiebebahnhöfe in Österreich und trägt wesentlich zur Effizienz des österreichischen Güterverkehrsnetzes bei."}]'::jsonb, ''),
  ('guetatoeaminaeu-wiin-inzasduaf', 'Gütatöaminäu Wiin-Inzasduaf', '', '', '', '', 'Güterterminal Wien-Inzersdorf', '[{"kategorie": "allg.", "text": "\"zentraler Knotenpunkt für den Güterverkehr in Wien, auch bekannt als \"Güterzentrum Wien Süd\""}, {"kategorie": "", "text": "Am 2. August 2013 wurde der Grundstein gelegt, und am 5. Dezember 2016 wurde der Terminal offiziell eröffnet. Er befindet sich im Süden von Wien im Stadtteil [[Inzersdorf]], nahe der Schnittstelle der [[Pottendorfer]] Linie und der Schnellstraße [[S]]1, und dient als multifunktionaler Umschlagplatz für die intermodale Güterverkehrsabwicklung zwischen Schiene und Straße"}, {"kategorie": "", "text": "Der Terminal umfasst im Endausbau 55 Hektar und vereint verschiedene Funktionsbereiche für den Güterverkehr, darunter Betriebsgleise für den Bahnverkehr, einen Bereich für den Containerumschlag (KLV), eine Halle für den Stückgutumschlag (KL), und den Wagenladungsverkehr (WLV)"}, {"kategorie": "", "text": "Der Standort ist optimal an das hochrangige Schienen- und Straßennetz angebunden, wodurch innerstädtische Bahnverschiebungen minimiert und eine direkte Verbindung zu wichtigen Verkehrswegen hergestellt wird"}, {"kategorie": "", "text": "Der Güterterminal Wien-Inzersdorf konzentriert die Güterlogistik in Wien an einem Ort, nachdem ältere Frachtenbahnhöfe wie der [[Nordbahnhof]], der [[Nordwestbahnhof]] und der [[Frachtenbahnhof]] Matzleinsdorf aufgegeben wurden"}, {"kategorie": "", "text": "Dadurch wird der Güterverkehr effizienter abgewickelt, insbesondere an der wichtigen Schnittstelle zwischen Schiene und Straße, wodurch der Verkehr optimiert und die Logistikkosten gesenkt werden."}]'::jsonb, ''),
  ('guetazentrum-wiin-sued', 'Gütazentrum Wiin-Süd', '', '', '', '', 'Güterzentrum Wien Süd', '[{"kategorie": "allg.", "text": "\"zentraler Knotenpunkt für den Güterverkehr in Wien, auch bekannt als \"Güterterminal Wien-Inzersdorf\""}, {"kategorie": "", "text": "Am 2. August 2013 wurde der Grundstein gelegt, und am 5. Dezember 2016 wurde der Terminal offiziell eröffnet. Er befindet sich im Süden von Wien im Stadtteil [[Inzersdorf]], nahe der Schnittstelle der [[Pottendorfer]] Linie und der Schnellstraße [[S]]1, und dient als multifunktionaler Umschlagplatz für die intermodale Güterverkehrsabwicklung zwischen Schiene und Straße"}, {"kategorie": "", "text": "Der Terminal umfasst im Endausbau 55 Hektar und vereint verschiedene Funktionsbereiche für den Güterverkehr, darunter Betriebsgleise für den Bahnverkehr, einen Bereich für den Containerumschlag (KLV), eine Halle für den Stückgutumschlag (KL), und den Wagenladungsverkehr (WLV)"}, {"kategorie": "", "text": "Der Standort ist optimal an das hochrangige Schienen- und Straßennetz angebunden, wodurch innerstädtische Bahnverschiebungen minimiert und eine direkte Verbindung zu wichtigen Verkehrswegen hergestellt wird"}, {"kategorie": "", "text": "Der Güterterminal Wien-Inzersdorf konzentriert die Güterlogistik in Wien an einem Ort, nachdem ältere Frachtenbahnhöfe wie der [[Nordbahnhof]], der [[Nordwestbahnhof]] und der [[Frachtenbahnhof]] Matzleinsdorf aufgegeben wurden"}, {"kategorie": "", "text": "Dadurch wird der Güterverkehr effizienter abgewickelt, insbesondere an der wichtigen Schnittstelle zwischen Schiene und Straße, wodurch der Verkehr optimiert und die Logistikkosten gesenkt werden."}]'::jsonb, ''),
  ('matzleinsduafa-frochtnbaunhof', 'Matzleinsduafa Frochtnbaunhof', '', '', '', '', 'Matzleinsdorfer Frachtenbahnhof', '[{"kategorie": "", "text": "Heute dient er als Anlage für Traktion, technische Services und den Personenverkehr. Das Gelände wird primär für Wartungs-, Reparatur- und Servicearbeiten an Zügen und Lokomotiven genutzt und bildet ein zentrales Betriebszentrum für den Wiener Hauptbahnhof"}, {"kategorie": "", "text": "Die Servicehalle am Frachtenbahnhof Matzleinsdorf ist240 Meter lang und 73 Meter breit, mit einer Höhe von bis zu 10 Metern. Die Halle besteht aus Holz- und Betonteilen und hat Wartungsgruben sowie einen Fluchttunnel. Das angrenzende Betriebsgebäude ist ebenfalls 240 Meter lang, hat fünf Stockwerke und wurde komplett aus Stahlbeton gebaut"}, {"kategorie": "", "text": "Zusätzlich gibt es zwei kleinere Hallen, in denen spezielle Maschinen zur Reparatur von Zügen untergebracht sind. Um die Anlage zugänglich zu machen, wurden Brücken und ein Tunnel für das Personal gebaut"}, {"kategorie": "", "text": "Die gesamte Anlage wird von den ÖBB für die Wartung von Zügen genutzt. Sie verfügt über moderne Einrichtungen, wie eine spezielle Maschine, die die Radsätze der Züge dreht und repariert"}, {"kategorie": "", "text": "Die Anlage ist so konzipiert, dass Züge in einem Durchfahrbetrieb gewartet werden können, was die Standzeiten minimiert und eine erhebliche Effizienzsteigerung ermöglicht. Dies spart den ÖBB in den ersten Betriebsjahren geschätzte zehn Millionen Euro"}, {"kategorie": "", "text": "Der [[Bahnhof]] Matzleinsdorfer Platz wird im Rahmen der U-Bahn-Erweiterung modernisiert, mit einer neuen Straßenbahn- und U-Bahn-Station, die 2028 fertiggestellt werden soll."}]'::jsonb, ''),
  ('baunhof-matzleinsduafa-plotz', 'Baunhof Matzleinsduafa Plotz', '', '', '', '', 'Bahnhof Matzleinsdorfer Platz', '[{"kategorie": "allg.", "text": "\"wichtiger Verkehrsknotenpunkt im 10. Wiener Gemeindebezirk (Favoriten), der Teil der [[S-Bahn-Stammstrecke]] ist und sowohl eine [[ÖBB-Haltestelle]] als auch eine zukünftige U-Bahn-Station der Linie U2 umfasst (auch bekannt als Haltestelle Matzleinsdorfer Platz)\""}, {"kategorie": "", "text": "Neben der Haltestelle befindet sich ein betrieblicher Stützpunkt der [[ÖBB]], in dem Wartungs- und Servicearbeiten für Lokomotiven und Reisezugwagen durchgeführt werden"}, {"kategorie": "", "text": "Die Station wurde im Laufe der Jahre mehrfach modernisiert, um den wachsenden Anforderungen des Verkehrs gerecht zu werden. Seit 2009 halten auch Regionalzüge in der Haltestelle, die barrierefrei zugänglich ist"}, {"kategorie": "", "text": "Eine U-Bahn-Station der Linie U2 wird derzeit unter der bestehenden Anlage errichtet und soll 2028 in Betrieb gehen. Die U-Bahn wird eine wichtige Verbindung zwischen der S-Bahn und anderen öffentlichen Verkehrsmitteln schaffen, um die Verkehrsbelastung im südlichen Wien zu verringern."}]'::jsonb, ''),
  ('pressbuaga-baun', 'Pressbuaga Baun', '', '', '', '', 'Pressburger Bahn', '[{"kategorie": "allg.", "text": "\"historische, 1914 eröffnete direkte elektrische Bahnverbindung zwischen Wien und Pressburg (heute Bratislava), die über Schwechat und Wolfsthal führte (auch \"Wien-Bratislava Eisenbahn\" genannt)\""}, {"kategorie": "", "text": "Die 70 Kilometer lange Strecke, die sowohl Stadt- als auch Überlandabschnitte umfasste, war eine der ersten elektrifizierten Bahnstrecken in der Region und diente dem Personen- und Güterverkehr. Auf der Strecke wurde ein kombiniertes Gleichstrom- und Wechselstromsystem verwendet, um den städtischen und ländlichen Verkehr effizient zu bedienen"}, {"kategorie": "", "text": "Während der [[Ersten]] Republik und insbesondere nach dem [[Zweiten]] Weltkrieg verlor die Strecke an Bedeutung, wurde jedoch bis heute teilweise im Rahmen der [[Wiener]] S-Bahn, insbesondere als S7, genutzt"}, {"kategorie": "", "text": "Der Verkehr auf der slowakischen Seite wurde 1945 eingestellt, doch die Bahn blieb ein wichtiges historisches Beispiel für den frühen grenzüberschreitenden Bahnverkehr in Mitteleuropa."}]'::jsonb, ''),
  ('pottnduafa-linii', 'Pottnduafa Linii', '', '', '', '', 'Pottendorfer Linie', '[{"kategorie": "allg.", "text": "\"Bahnstrecke zwischen Wien und Niederösterreich, die ursprünglich von Fabriksbesitzern und Industriellen wie Ignaz Eisler und Heinrich Drasche geplant wurde und 1871 eröffnet wurde\""}, {"kategorie": "", "text": "Sie verbindet den [[Bahnhof]] Wien Meidling über Ebreichsdorf und Ebenfurth mit Wiener Neustadt und erschließt damit den mittleren Teil des [[Wiener]] Beckens"}, {"kategorie": "", "text": "Die Strecke, die einst als Nebenstrecke der [[Südbahn]] diente, wurde im Laufe der Jahre ausgebaut und elektrifiziert"}, {"kategorie": "", "text": "Seit 2023 ist sie vollständig zweigleisig, um die stark befahrene Südbahn zu entlasten und Kapazitäten für den Personen- und Güterverkehr zu erweitern"}, {"kategorie": "", "text": "Sie ist heute Teil des Kernnetzes der [[ÖBB]] und wird auch als [[Schnellbahnlinie]] genutzt."}]'::jsonb, ''),
  ('wiina-donaulaendn', 'Wiina Donauländn', '', '', '', '', 'Wiener Donauländen', '[{"kategorie": "allg.", "text": "\"eine seit etwa 1890 gebräuchliche Bezeichnung für die Uferstraßen entlang des Hauptstroms der Donau und des Donaukanals in Wien\""}, {"kategorie": "", "text": "Diese Uferstraßen entstanden im Zuge der [[Donauregulierung]] und umfassen wichtige Verkehrswege wie den [[Handelskai]] und die [[Donauuferbahn]]"}, {"kategorie": "", "text": "Am [[Donaukanal]] tragen verschiedene Straßen entlang des Ufers den Namen \"Lände\", wie die [[Nußdorfer]] Lände, die [[Heiligenstädter]] Lände, die [[Spittelauer]] Lände, die [[Brigittenauer]] Lände, die [[Rossauer]] Lände, die [[Weißgerber]] Lände, die [[Erdberger]] Lände und die [[Simmeringer]] Lände"}, {"kategorie": "", "text": "Eine \"Lände\" ist im Schifffahrtskontext eine einfache Anlegestelle an einem Gewässer, die als einfacher Binnenhafen dient, wobei das Ufer befestigt ist, aber ohne aufwendige Hafenstrukturen wie separate Hafenbecken."}]'::jsonb, ''),
  ('lainza-tunnoeoe', 'Lainza Tunnöö', '', '', '', '', 'Lainzer Tunnel', '[{"kategorie": "allg.", "text": "\"12 km langer Bahntunnel in Wien, der die [[Südbahn]], [[Donauländebahn]], [[Westbahn]] und den [[Wienerwaldtunnel]] verbindet\""}, {"kategorie": "", "text": "Er ist Teil des europäischen Hochgeschwindigkeitsnetzes (TEN), das Städte wie Paris, Wien, Budapest und Bratislava miteinander verbindet"}, {"kategorie": "", "text": "Der Tunnel verläuft unter dem [[Lainzer]] Tiergarten und dient der Kapazitätssteigerung für den Reise- und Güterverkehr durch Wien"}, {"kategorie": "", "text": "Die Bauarbeiten begannen 1999, und der Tunnel wurde 2012 in Betrieb genommen"}, {"kategorie": "", "text": "Er ermöglicht eine schnellere Durchfahrt für Züge und entlastet bestehende Bahnstrecken. Die Baukosten betrugen 1,3 Milliarden Euro."}]'::jsonb, ''),
  ('wiina-schnoebaunring', 'Wiina Schnöbaunring', '', '', '', '', 'Wiener Schnellbahnring', '[{"kategorie": "", "text": "Ursprünglich als Erweiterung der Linie S45 angedacht, sieht der Plan eine Verlängerung der S45 vom [[Handelskai]] entlang der [[Donau]] bis zum [[Praterkai]] vor, begleitet von einer Taktverdichtung"}, {"kategorie": "", "text": "Neben der Verlängerung der S45 entlang der Donau sollen neue Stationen wie [[Reichsbrücke]] und Donaumarina entstehen"}, {"kategorie": "", "text": "Die S80 bleibt weiterhin von Hütteldorf nach Aspern Nord bestehen, und der Ausbau der [[Verbindungsbahn]] bietet die Möglichkeit, die westlichen Bezirke direkt an die [[Süd-]] und [[Westbahn]] anzubinden"}, {"kategorie": "", "text": "Dieses Projekt soll bis 2025 umgesetzt werden und bietet eine Alternative zur stark frequentierten U6 sowie eine neue Nord-Süd-Verbindung für den Westen Wiens."}]'::jsonb, ''),
  ('wiina-schdaummschdreckn', 'Wiina Schdaummschdreckn', '', '', '', '', 'Wiener Stammstrecke', '[{"kategorie": "", "text": "Die 13 Kilometer lange, elektrifizierte Strecke verbindet elf Stationen und führt vom [[Bahnhof]] Wien Floridsdorf im Nordosten bis zum [[Bahnhof]] Wien Meidling im Südwesten"}, {"kategorie": "", "text": "Sie folgt teilweise der historischen Trasse der [[Nordbahn]] und der [[Verbindungsbahn]] und durchquert wichtige Verkehrsknotenpunkte wie den [[Praterstern]], den [[Bahnhof]] Wien Mitte und den [[Hauptbahnhof]]"}, {"kategorie": "", "text": "Fast 700 Züge befördern täglich rund 270.000 Passagiere auf dieser Strecke, die eine wesentliche Rolle im Wiener Nahverkehr spielt."}]'::jsonb, ''),
  ('kaisarin-elisabeth-baun', 'Kaisarin-Elisabeth-Baun', '', '', '', '', 'Kaiserin-Elisabeth-Bahn', '[{"kategorie": "allg.", "text": "eine der bedeutendsten Bahnstrecken Österreichs, die Wien und Salzburg miteinander verbindet (heute [[Westbahn]])"}, {"kategorie": "", "text": "Die 1856 gegründete Strecke wurde nach Kaiserin Elisabeth ([[Sisi]]), der Frau von [[Kaiser]] Franz Joseph I., benannt und war ein wichtiges Projekt zur Schaffung einer schnellen Verbindung zwischen Wien und den westlichen Teilen des Kaiserreichs"}, {"kategorie": "", "text": "Die gesamte Strecke von Wien nach Salzburg wurde 1860 fertiggestellt. Im Laufe der Zeit wurde die Westbahn kontinuierlich ausgebaut und modernisiert, insbesondere durch den viergleisigen Ausbau und die Elektrifizierung"}, {"kategorie": "", "text": "Die Westbahn spielt heute eine zentrale Rolle im österreichischen Bahnnetz und gehört zu den am stärksten frequentierten Strecken des Landes. Sie ist sowohl für den Personen- als auch für den Güterverkehr von großer Bedeutung und Teil des Trans-Europäischen Verkehrsnetzes (TEN)"}, {"kategorie": "", "text": "Modernisierungen und Hochgeschwindigkeitsabschnitte ermöglichen Fahrten mit bis zu 250 km/h, wodurch die Fahrzeiten zwischen Wien und Salzburg erheblich verkürzt wurden. Neben den [[ÖBB]] bedient auch das private Eisenbahnunternehmen WESTbahn GmbH die Strecke"}, {"kategorie": "", "text": "Die Strecke umfasst zahlreiche Tunnel, darunter den [[Lainzer]] Tunnel und den [[Wienerwaldtunnel]], und führt durch den landschaftlich reizvollen [[Wienerwald]]"}, {"kategorie": "", "text": "Sie hat Anschluss an wichtige Städte und Bahnknotenpunkte wie St. Pölten, Linz, Wels und Salzburg und verbindet damit die wichtigsten urbanen Zentren Österreichs."}]'::jsonb, ''),
  ('uaban-loritz-plotz', 'Uaban-Loritz-Plotz', '', '', '', '', 'Urban-Loritz-Platz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 7. Wiener Gemeindebezirk ([[Neubau]]), der nach Urban Loritz benannt ist\""}, {"kategorie": "", "text": "Urban Loritz (1807–1881) war ein angesehener Seelsorger und sozialer Vordenker. Er war Mitglied des Benediktinerordens und wirkte ab 1841 als Pfarrer in der Pfarre [[Schottenfeld]], wo er besonders für seine soziale Arbeit und sein Engagement für die Armen und Benachteiligten bekannt war"}, {"kategorie": "", "text": "Urban Loritz gründete 1853 eine Kleinkinder-Bewahranstalt zur Betreuung und Versorgung verwahrloster Kinder und war maßgeblich an der künstlerischen Ausgestaltung seiner Pfarrkirche in der Westbahnstraße 17 beteiligt"}, {"kategorie": "", "text": "Loritz war eine sehr volkstümliche und charismatische Priesterpersönlichkeit, die versuchte, soziale Spannungen in der wachsenden Stadt Wien zu lindern"}, {"kategorie": "", "text": "Zu seinen Ehren errichtete die Stadt Wien ein Denkmal auf dem Urban-Loritz-Platz: eine Bronzebüste auf einem Granitsockel, gestaltet von Franz Seifert und 1901 enthüllt"}, {"kategorie": "", "text": "Die Büste wurde während des [[Zweiten]] Weltkriegs entfernt, befindet sich aber heute wieder im südlichen Teil der Platzanlage"}, {"kategorie": "", "text": "Der Urban-Loritz-Platz ist ein wichtiger Verkehrsknotenpunkt in Wien und liegt am westlichen Ende der [[Westbahnstraße]]."}]'::jsonb, ''),
  ('wiina-donaukanalbruckn', 'Wiina Donaukanalbruckn', '', '', '', '', 'Wiener Donaukanalbrücken', '[{"kategorie": "allg.", "text": "\"all jene Brücken, die den Donaukanal in Wien als Straßen-, Bahn- oder Fußgängerbrücken überqueren\""}, {"kategorie": "", "text": "Viele Donaukanalbrücken wurden im Zuge der [[Wiener]] Operation am Ende des [[Zweiten]] Weltkriegs zerstört und ach 1945 vielfach durch moderne Stahlbetonbrücken ersetzt"}, {"kategorie": "", "text": "Der Donaukanal, einst ein wichtiger Verkehrsweg, war schon in der Römerzeit von Brücken überquert. Die älteste nachweisbare Brücke war die Schlagbrücke aus dem Jahr 1439, die später zur [[Schwedenbrücke]] wurde. Diese Brücken verbanden die Stadt mit dem nordöstlichen Umland"}, {"kategorie": "", "text": "Die wichtigsten Donaukanalbrücken sind heute: (i) [[Schemerlbrücke]] (1898, überspannt das [[Nussdorfer]] Wehr), (ii) [[Heiligenstädter]] Brücke (1883-1889, bedeutende Straßenbrücke im Norden Wiens), (iii) [[Friedensbrücke]] (1924-1926, ursprünglich als Brigittabrücke bekannt, verbindet den Alsergrund (9. Bezirk) und die Brigittenau (20. Bezirk), (iv) [[Schwedenbrücke]] (1909-1911 - ehemals als Ferdinandsbrücke bezeichnet, gehört zu den ältesten Brücken über den Donaukanal, verbindet die Bezirke Innere Stadt [1. Bezirk] und Leopoldstadt [2. Bezirk]), (v) [[Aspernbrücke]] (1913-1919 verbindet die Bezirke Innere Stadt [1. Bezirk] und Leopoldstadt [2. Bezirk]), (vi) [[Erdberger]] Brücke (1971 - moderne Straßenbrücke, überquert im Zuge der Stadtautobahn Südosttangente beim Knoten Wien Prater den Donaukanal und verbindet die Landstraße [3. Bezirk] mit der Leopoldstadt [2. Bezirk]), (vii) [[Rossauer]] Brücke (1983 errichtet, verbindet den 9. Bezirk [Alsergrund] mit dem 2. Bezirk [Leopoldstadt]);  (viii) [[Augartenbrücke]] (errichtet 1929-1931, verbindet den 9. und den 2. Bezirk [Alsergrund bzw. Leopoldstadt]), (ix) [[Salztorbrücke]] (errichtet 1884-1886, ersetzt den ehemaligen Karlskettensteg und verbindet den 1. und 2. Bezirk [Innere Stadt und Leopoldstadt]);  (x) [[Marienbrücke]] (ursprünglich als Rotenturmbrücke bekannt, von 1905 bis 1906 neu errichtet, verbindet den 1. und 2. Bezirk [Innere Stadt und Leopoldstadt]); (xi) [[Franzensbrücke]] (errichtet 1847-1848 errichtet, gehört zu den ältesten Brücken über den Donaukanal, verbindet die Bezirke 2 und 3 [Leopoldstadt und Landstraße]), (xii) [[Rotundenbrücke]] (erbaut 1871/1872, verbindet die Bezirke 2 und 3 [Leopoldstadt und Landstraße]), (xiii) [[Stadionbrücke]] (errichtet ursprünglich von 1874 bis 1876, umgebaut 1936, verbindet die Bezirke 2 und 3 [Leopoldstadt und Landstraße]), (xiv) [[Seitenhafenbrücke]] (2011 eröffnete Straßenbrücke, verbindet die Seitenhafenstraße am linken Ufer, im 2. Bezirk [Leopoldstadt], mit der Haidequerstraße am rechten Ufer, im 11. Bezirk [Simmering], (xv) [[Freudenauer]] Hafenbrücke (errichtet 1958, überquert den Donaukanal im Bereich des Freudenauer Hafens und verbindet das Hafengebiet im 2. Bezirk [Leopoldstadt] mit dem 11. Bezirk [Simmering]), (xvi) [[Schrägseilbrücke]] (verbindet die Bezirke Simmering und Leopoldstadt, ist Teil der A4 Ostautobahn und führt den stadteinwärts fahrenden Verkehr zum Knoten Prater), (xvii) [[Spittelauer]] Brücke (erbaut 1992, verbindet die Bezirke Döbling [19. Bezirk] und Brigittenau [20.Bezirk]), sowie (xviiii) [[Winterhafenbrücke]] (erbaut 2007-2008 - verbindet den Stadtteil Albern [heute Teil des 11. Bezirkes, Simmering], mit dem 2. Bezirk [Leopoldstadt]."}]'::jsonb, ''),
  ('eadbeaga-bruckn', 'Eadbeaga Bruckn', '', '', '', '', 'Erdberger Brücke', '[{"kategorie": "allg.", "text": "\"bedeutende Schalenbrücke, welche als Teil der Autobahn A 23 ([[Südosttangente]] Wien) den [[Donaukanal]] überquert\""}, {"kategorie": "", "text": "Sie wurde von 1969 bis 1971 errichtet und nach der ehemaligen Vorstadt [[Erdberg]] benannt"}, {"kategorie": "", "text": "Die Brücke verbindet die Bezirke [[Landstraße]] (3. Bezirk) und [[Leopoldstadt]] (2. Bezirk)"}, {"kategorie": "", "text": "Mit einer Breite von 42 Metern und einer Spannweite von 147 Metern überquert die Brücke den Donaukanal und dient heute als wichtige Verkehrsanbindung im Knoten Wien Prater, dem Übergang zur [[Ostautobahn]] (A4)"}, {"kategorie": "", "text": "Die Brücke, die für den Autoverkehr zehnspurig ausgebaut ist, wurde ursprünglich in der innovativen Schalenbauweise errichtet, eine Pionierleistung österreichischer Ingenieurskunst. In den Jahren 2015/2016 wurde die alte Brücke abgerissen und durch zwei neue Brücken ersetzt, die heute Teil des [[Knoten]] Prater sind."}]'::jsonb, ''),
  ('knotn-prooda', 'Knotn Prooda', '', '', '', '', 'Knoten Prater', '[{"kategorie": "", "text": "Dieser Knotenpunkt ist von großer verkehrstechnischer Bedeutung, da er als zentrale Verbindungsstelle im hochrangigen Straßennetz der Ostregion dient. Täglich passieren etwa 190.000 Fahrzeuge die [[Erdberger]] Brücke, die ebenfalls Teil dieses Knotens ist"}, {"kategorie": "", "text": "Im Rahmen von Bauarbeiten zwischen 2010 und 2017 wurde die Erdberger Brücke neu errichtet, da die alte Konstruktion aus den 1970er Jahren als wirtschaftlich nicht mehr sanierbar eingestuft wurde"}, {"kategorie": "", "text": "Die Bauphasen beinhalteten die Errichtung von Entflechtungsbauwerken, um den Verkehrsfluss zu optimieren, sowie die Sanierung und Verbreiterung der Brücke. Dies erhöhte die Kapazität und trug zur verbesserten Verkehrsanbindung sowohl im innerstädtischen als auch im überregionalen Verkehr bei"}, {"kategorie": "", "text": "Die umfassenden Bauarbeiten am Knoten Prater und der [[Erdberger]] Brücke zielten darauf ab, die Verkehrsbelastung durch moderne Infrastrukturmaßnahmen zu bewältigen und langfristig zu entflechten."}]'::jsonb, ''),
  ('wiina-donaubruckn', 'Wiina Donaubruckn', '', '', '', '', 'Wiener Donaubrücken', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsverbindungen, welche die [[Donau]] und ihre Nebenarme in Wien überqueren und den älteren Teil Wiens am rechten Donauufer mit den jüngeren Bezirken am linken Donauufer miteinander verbinden\""}, {"kategorie": "", "text": "Die Geschichte der Brücken über die Donau reicht bis ins 15. Jahrhundert zurück, als vorerst nur schmalere Arme des Flusses überquert wurden, wie der [[Donaukanal]]"}, {"kategorie": "", "text": "Die erste dauerhafte Brücke über den Hauptstrom wurde 1440 erbaut, um den Handel und den Personenverkehr zu erleichtern. Aufgrund häufiger Überschwemmungen und Veränderungen im Flussverlauf war der Brückenbau eine große Herausforderung, wobei die ersten Brücken hauptsächlich aus Holz gebaut wurden"}, {"kategorie": "", "text": "Überörtliche Bedeutung haben heute nur jene Brücken, die sowohl über die [[Donau]] als auch über die [[Donauinsel]] und die [[Neue]] Donau führen und somit Verbindungen zwischen dem Stadtgebiet südlich (rechtsufrig) und nördlich (linksufrig) der Donau herstellen"}, {"kategorie": "", "text": "Derzeit führen elf Brücken über beide Stromarme. Die wichtigsten Straßenbrücken hiervon sind: (i) die Nordbrücke (erbaut 1962-1964, verbindet den 19. und 20. Bezirk [Döbling und Brigittenau]), (ii) die Floridsdorfer Brücke (erstmals 1876 eröffnet, in den 1970-er Jahren neu erbaut, verbindet den 20. und 21. Bezirk [Brigittenau und Floridsdorf]), (iii) Brigittenauer Brücke (erbaut 1981-1982, verbindet den 20. und 21. Bezirk [Brigittenau und Floridsdorf), (iv) Reichsbrücke (1976 eingestürzt, dann neu erbaut und 1980 wieder eröffnet, verbindet den 2. und 22. Bezirk [Leopoldsdorf und Donaustadt]), sowie (v) Praterbrücke (achtspurige Autobahnbrücke, erbaut 1967-1970, verbindet den 2. und 22. Bezirk [Leopoldstadt und Donaustadt])"}, {"kategorie": "", "text": "Die wichtigsten Fußgänger- und Radfahrerbrücken sind: (i) Jedleseer Brücke (erbaut 1983, über die Neue Donau, verbindet die Floridsdorfer Stadtteile Jedlesee und Schwarzlackenau), (ii) Steinitzsteg (erbaut 1994-1995, früher Nordsteg, über Donau und Neue Donau, verbindet den 20. und 21. Bezirk [Brigittenau und Floridsdorf]), (iii) Georg-Danzer-Steg (erbaut 1991-1996, auch Bahnbrücke über Donau und Neue Donau, verbindet den 20. und 21. Bezirk [Brigittenau und Floridsdorf]), (iv) Ponte Cagrana (erbaut 2000, Pontonbrücke über die Neue Donau im 22. Bezirk [Donaustadt]), (v) Kaisermühlenbrücke (erbaut 1993, Schrägseilbrücke über die Neue Donau  im 22. Bezirk [Donaustadt]), (vi) Steinspornbrücke (erbautz 1974, führt über die Neue Donau und verbindet die obere Lobau mit der Donauinsel), (vii) Walulisobrücke (1997-98 erbaut, Pontonbrücke über die Neue Donau im 22. Wiener Gemeindebezirk [Donaustadt]), (vii) Wehr 1 (erbaut 1976-1978, Wehranlage, überquert als Spannbetonbrücke die Neue Donau zur Donauinsel), (viii) Wehr 2 (erbaut 1988, Wehranlage, überquert als Spannbetonbrücke die Neue Donau zur Donauinsel), sowie (ix) Kraftwerk Freudenau (erbaut 1992-1998, verbindet den Hafen Freudenau mit der Donauinsel)."}]'::jsonb, ''),
  ('maura-pfoakiachn', 'Maura Pfoakiachn', '', '', '', '', 'Maurer Pfarrkirche', '[{"kategorie": "", "text": "Sie ist dem heiligen Erhard geweiht und befindet sich an der Ecke [[Endresstraße]] und [[Speisinger]] Straße"}, {"kategorie": "", "text": "Die Kirche hat eine lange Geschichte, die bis ins 15. Jahrhundert zurückreicht. Ursprünglich befand sich in Mauer die Engelsburg mit der Kapelle St. Andreas, die zur Pfarre [[Atzgersdorf]] gehörte"}, {"kategorie": "", "text": "Um 1450 wurde am heutigen [[Maurer]] Hauptplatz eine Kirche zu Ehren des heiligen Erhard erbaut, von der der Wehrturm und das gotische Presbyterium (heute Seitenkapelle) erhalten geblieben sind"}, {"kategorie": "", "text": "Die Kirche wurde mehrfach zerstört, unter anderem während der [[Ersten]] Türkenbelagerung Wiens 1529, aber immer wieder aufgebaut. Im Jahr 1783 wurde [[Mauer]] im Rahmen einer Pfarrneuorganisation unter Joseph II. schließlich zur eigenständigen Pfarre erhoben"}, {"kategorie": "", "text": "Eine bedeutende Erweiterung und Neuausrichtung der Kirche erfolgte von 1934 bis 1936 unter dem Architekten Clemens Holzmeister, der das Gebäude in seiner heutigen Nord-Süd-Ausrichtung gestaltete. Die spätgotische Apsis wurde zur Seitenkapelle, während ein neuer großer Saalraum das Zentrum der Kirche bildet. Der Kirchturm, im unteren Bereich gotisch, ist barock gestaltet"}, {"kategorie": "", "text": "Zu den bedeutendsten Kunstwerken der Kirche zählen der Hochaltar, der dem Maler Paul Troger zugeschrieben wird, sowie eine Pietà von Giovanni Giuliani (1710). Die Kirche besitzt zudem wertvolle Glasfenster und Mosaike, die von Künstlern wie Albert Paris Gütersloh und Rudolf Holzinger gestaltet wurden."}]'::jsonb, ''),
  ('wiina-flua', 'Wiina Flua', '', '', '', '', 'Wiener Flur', '[{"kategorie": "allg.", "text": "\"große Wohnhausanlage im Stadtteil [[Siebenhirten]] im 23. Wiener Gemeindebezirk ([[Liesing]])\""}, {"kategorie": "", "text": "Sie wurde zwischen 1978 und 1980 nach Plänen der Architekten Klara Hautmann, Rudolf Hautmann und Friedrich Rollwagen errichtet, als Wien verstärkt in den Ausbau von Wohnraum investierte, um dem steigenden Bedarf an modernen Wohnungen gerecht zu werden"}, {"kategorie": "", "text": "Der \"Wiener Flur\" ist als großflächige Wohnanlage konzipiert, die mehrere hundert Wohneinheiten umfasst. Die Anlage zeichnet sich durch eine funktionale Architektur aus, die typische Elemente des modernen städtischen Wohnungsbaus der späten 1970er Jahre aufgreift. Die Gebäude sind meist mehrgeschossig"}, {"kategorie": "", "text": "Die Anlage spielt eine zentrale Rolle in der urbanen Entwicklung des 23. Bezirks Liesing und ist ein wichtiger Beitrag zur Schaffung von Wohnraum im wachsenden Wien der späten 1970er Jahre. Im Jahr 1951 hatte das Stadtviertel bei der Volkszählung 2839 Einwohner. Heute leben rund 8000 Menschen in Siebenhirten."}]'::jsonb, ''),
  ('siimhiatna-pfoakiachn', 'Siimhiatna Pfoakiachn', '', '', '', '', 'Siebenhirtener Pfarrkirche', '[{"kategorie": "", "text": "Diese Kirche ist die Nachfolgerin der alten Pfarrkirche, die im Zweiten Weltkrieg durch Bombentreffer 1944 zerstört wurde. Die neue Pfarrkirche wurde 1955 nach den Plänen des Architekten Herbert Schmidt erbaut und stellt ein schlichtes, aber markantes Bauwerk dar, das durch seine ruhige und bescheidene Architektur besticht"}, {"kategorie": "", "text": "Die Pfarrkirche St. Martin ist ein schlichter Bau mit einem freistehenden Glockenturm aus Beton, der 24 Meter hoch ist. Der Innenraum der Kirche wird durch eine Holzdecke mit sichtbaren Tragbalken geprägt, die dem Raum eine warme und einladende Atmosphäre verleiht"}, {"kategorie": "", "text": "Rechts vom Kirchenportal befindet sich ein Steinrelief, das Christus darstellt. Dieses Werk stammt vom akademischen Bildhauer Bohdan Zarovsky und trägt die Inschrift: „Ich bin der gute Hirte. Ich kenne die meinen und die meinen kennen mich.“ Die Skulptur des Guten Hirten ist ein zentrales Symbol der Kirche und steht sinnbildlich für die Fürsorge des heiligen Martin, dem die Kirche geweiht ist"}, {"kategorie": "", "text": "Der Volksaltar, der 1967 aufgestellt wurde, enthält Reliquien der Heiligen Concordius und Valeria, die der Kirche eine besondere spirituelle Bedeutung verleihen. Die Orgel, die 1956 aus der Pfarrkirche [[Ober-St]].-Veit angekauft wurde, stammt aus dem Jahr 1864."}]'::jsonb, ''),
  ('pfoakiachn-koiksbuag', 'Pfoakiachn Koiksbuag', '', '', '', '', 'Pfarrkirche Kalksburg', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 23. Wiener Gemeindebezirk ([[Liesing]]), im Stadtteil [[Kalksburg]] (auch bekannt als die Pfarrkirche \"Zum heiligen Petrus in Ketten\")"}, {"kategorie": "", "text": "Die heutige Pfarrkirche wurde von Franz Ritter von Mack, einem wohlhabenden Hofjuwelier, im späten 18. Jahrhundert gestiftet. Mack ließ die Kirche bauen, nachdem er die Herrschaft Kalksburg erworben hatte. Die Weihe der Kirche fand im Jahr 1801 statt"}, {"kategorie": "", "text": "Der Bau der Kirche steht im Zusammenhang mit Macks weiteren Bauprojekten in Kalksburg, darunter auch die Errichtung des [[Kalksburger]] Friedhofs und der Ausbau seines schlossähnlichen Besitzes „Mon Perou“"}, {"kategorie": "", "text": "Nachdem die Jesuiten 1856 den Besitz „Mon Perou“ wiedererwarben, errichteten sie in der Nähe der Kirche ein Konvikt (Internat), das bis heute als Jesuitenkollegium Kalksburg bekannt ist"}, {"kategorie": "", "text": "Die Kalksburger Pfarrkirche ist ein schlichtes barockes Bauwerk mit einer eleganten und zurückhaltenden Architektur, die typisch für diese Zeit ist. Die erhöhte Lage der Kirche unterstreicht ihre Besonderheit"}, {"kategorie": "", "text": "Im Inneren entspricht sie der spätbarocken Tradition. Die Deckenfresken in der Kirche zeigen Szenen wie die Schöpfung der Welt, das Jüngste Gericht und das Letzte Abendmahl. Die Seitenaltarbilder stellen links die heilige Helena und rechts den heiligen Franziskus dar, wie er seine Stigmata erhält"}, {"kategorie": "", "text": "Diese Kunstwerke wurden 1799 von Josef Keller geschaffen. Der Hochaltar wurde von Hubert Maurer gestaltet, und die Orgel baute Anton Pfliegler im Jahr 1801. Im Inneren der Kirche befindet sich außerdem ein Marmordenkmal für Franz und Helene Ritter von Mack, das von Josef Kässmann stammt."}]'::jsonb, ''),
  ('wiina-donauaun', 'Wiina Donauaun', '', '', '', '', 'Wiener Donauauen', '[{"kategorie": "allg.", "text": "ausgedehntes Au- und Feuchtgebiet entlang der [[Donau]], das sich im Südosten der Stadt befindet und Teil des [[Nationalparks]] Donau-Auen ist\""}, {"kategorie": "", "text": "Dieses geschützte Gebiet umfasst die natürlichen Auwälder, Altarme und Feuchtwiesen, die sich entlang der Donau erstrecken und eine bedeutende ökologische Rolle spielen. Es erstreckt sich von Wien bis in die östlich gelegenen Regionen Niederösterreichs und ist eines der letzten großen, weitgehend intakten Flussauenlandschaften Mitteleuropas"}, {"kategorie": "", "text": "Die Wiener Donauauen, insbesondere die [[Lobau]], bieten Lebensraum für eine große Vielfalt an Tieren und Pflanzen, darunter viele seltene und gefährdete Arten. Das Gebiet ist durch regelmäßige Überflutungen der Donau geprägt, die entscheidend für die natürliche Dynamik und die Erhaltung des Auwalds sind"}, {"kategorie": "", "text": "Darüber hinaus sind die Donauauen ein beliebtes Naherholungsgebiet für die Wiener Bevölkerung und bieten zahlreiche Möglichkeiten für Freizeitaktivitäten wie Wandern, Radfahren, Vogelbeobachtung und Bootfahren"}, {"kategorie": "", "text": "Gleichzeitig stehen die Wiener Donauauen unter strengem Naturschutz, um die empfindlichen Ökosysteme zu erhalten."}]'::jsonb, ''),
  ('nationalpark-donau-aun', 'Nationalpark Donau-Aun', '', '', '', '', 'Nationalpark Donauauen', '[{"kategorie": "allg.", "text": "\"geschütztes Naturschutzgebiet, das sich entlang der [[Donau]] zwischen [[Wien]] und Bratislava erstreckt\""}, {"kategorie": "", "text": "Es umfasst eine der letzten großen, weitgehend unverbauten Flussauenlandschaften Mitteleuropas. Der Nationalpark schützt die natürlichen Auwälder, Feuchtgebiete, Altarme und Flusslandschaften entlang der Donau, die von regelmäßigen Hochwässern geprägt sind und eine hohe biologische Vielfalt aufweisen"}, {"kategorie": "", "text": "Der Nationalpark Donau-Auen erstreckt sich über eine Fläche von rund 9.600 Hektar und umfasst sowohl Gebiete in Wien (insbesondere die [[Lobau]]) als auch in Niederösterreich"}, {"kategorie": "", "text": "Der Nationalpark wurde 1996 gegründet, um die wertvollen Auenlandschaften und die dort lebenden Tier- und Pflanzenarten vor Eingriffen zu bewahren. Das Gebiet bietet Lebensraum für viele seltene und bedrohte Arten, wie zum Beispiel den Seeadler, den Eisvogel oder die Europäische Sumpfschildkröte"}, {"kategorie": "", "text": "Neben seiner ökologischen Bedeutung ist der Nationalpark auch ein beliebtes Ziel für Naturliebhaber und bietet zahlreiche Möglichkeiten für Freizeitaktivitäten wie Wandern, Radfahren, Kanufahren und geführte Naturtouren. Gleichzeitig steht der Nationalpark unter strengen Naturschutzauflagen, um die natürlichen Prozesse und die Artenvielfalt langfristig zu erhalten."}]'::jsonb, ''),
  ('schdaahof-gruende', 'Schdaahof-Gründe', '', '', '', '', 'Steinhof-Gründe', '[{"kategorie": "allg.", "text": "\"weitläufiges Erholungsgebiet im Westen Wiens, das sich über eine Fläche von etwa 42 Hektar erstreckt\""}, {"kategorie": "", "text": "Die Steinhof-Gründe liegen im 14. Wiener Gemeindebezirk ([[Penzing]]), in unmittelbarer Nähe zur [[Baumgartner]] Höhe und dem [[Otto-Wagner-Spital]]"}, {"kategorie": "", "text": "Die Steinhofgründe sind ein beliebtes Naherholungsgebiet für die Wiener Bevölkerung und bieten zahlreiche Möglichkeiten für Freizeitaktivitäten im Grünen"}, {"kategorie": "", "text": "Die Steinhofgründe waren ursprünglich Teil des Areals des Otto-Wagner-Spitals, das Anfang des 20. Jahrhunderts als „Niederösterreichische Landes-Heil- und Pflegeanstalt für Nerven- und Geisteskranke Am Steinhof“ erbaut wurde. Die Anlage wurde nach Plänen des berühmten Architekten Otto Wagner gestaltet und ist ein bedeutendes Beispiel für den Jugendstil in Wien"}, {"kategorie": "", "text": "In den 1980er Jahren wurden die Steinhofgründe der Öffentlichkeit als Erholungsgebiet zugänglich gemacht. Die Flächen, die früher den Patienten des Spitals zur Erholung dienten, wurden in ein öffentliches Naherholungsgebiet umgewandelt und bieten heute einen wichtigen Rückzugsort für die Bewohner Wiens."}]'::jsonb, ''),
  ('do-ziagds-wiarin-an-voglheisl', 'Do ziagds wiarin an Voglheisl', '', '', '', '', 'Hier zieht es wie in einem Vogelhäuschen', '[{"kategorie": "", "text": "Hier pfeift der Wind durch alle Ritzen!  2. Hier zieht es wie in einem Windkanal!  3. Die Zugluft hier ist mehr als kräftig!"}]'::jsonb, ''),
