  ('du-blaeaede-rean', 'Du blääde Rean!', '', '', '', '', 'Du blöde Rehren!', '[{"kategorie": "wörtlich", "text": "\"Du blöde Röhren!\"  2. Du dumme Heulsuse!  3. Du blöder Jammerlappen!"}]'::jsonb, ''),
  ('kann-rewach-mochn', 'kann Rewach mochn', '', '', '', '', 'keinen Rebbach machen', '[{"kategorie": "", "text": "keinen Reibach machen"}, {"kategorie": "", "text": "keinerlei Gewinn machen (abgeleitet vom jiddischen Wort \"réwach\" = \"Zins\" bzw. \"Einkommen\" bzw. \"Profit\")"}]'::jsonb, ''),
  ('do-raewaed-si-nix', 'Do räwäd si nix!', '', '', '', '', 'Da rebelt sich nichts!', '[{"kategorie": "", "text": "Da wird man nicht viel ernten können!  2. Da ist kein Gewinn zu erwarten!  3. Da besteht kaum Aussicht auf Erfolg!"}]'::jsonb, ''),
  ('mi-reckts', 'Mi reckts!', '', '', '', '', 'Mich reckt es!', '[{"kategorie": "", "text": "Ich hab Brechreiz!  2. Ich muss mich gleich übergeben!  3. Ich muss gleich [[speiben]]!"}]'::jsonb, ''),
  ('reed-oda-scheiss-buchschdobn', 'Reed oda scheiss Buchschdobn!', '', '', '', '', 'Red oder scheiß Buchstaben!', '[{"kategorie": "wörtlich", "text": "\"Rede oder scheiße Buchstaben!\"  2. (scherzhaft für): Lass die Katze endlich aus dem Sack!  3. Spuck oder scheiß die Wörter endlich aus!  4. Jetzt rede mal Klartext!"}]'::jsonb, ''),
  ('des-is-a-reed', 'Des is a Reed!', '', '', '', '', 'Das ist eine Rede!', '[{"kategorie": "wörtlich", "text": "\"Das lässt sich hören!\"  2. \"Das ist Musik in meinen Ohren!\"  3. \"Das geht runter wie Öl!\"  4. \"Das ist mal ''ne Ansage!\""}]'::jsonb, 'Ka Reed!'),
  ('reed-in-a-sackal-und-stoeoe-s-vua-de-tia', 'Reed in a Sackal und stöö''s vua de Tia!', '', '', '', '', 'Rede in ein Sackerl und stelle es vor die Tür!', '[{"kategorie": "wörtlich", "text": "\"Sprich deine Worte in eine Tüte und stelle sie vor die Tür!\"  2. (scherzhaft für): \"Pack deine Worte ein und schick sie per Post!\"  3. Steck dein Gelaber in einen Umschlag und verschick es woanders!  4. Wenn du nicht schweigen kannst, dann sprich deine Worte in ein Sackerl und stelle es vor die Tür (falls du wirklich glaubst, dass sich dein sinnloses Gequatsche irgendwann später noch wer anhören will)"}]'::jsonb, ''),
  ('sog-mas-in-a-sackl-i-hoi-mas-spaeaeda-oo', 'Sog mas in a Sackl, I hoi mas spääda oo!', '', '', '', '', 'Sag es mir in ein Sackerl, ich hol''s mir später ab!', '[{"kategorie": "wörtlich", "text": "\"Sprich mir deine Worte in eine Plastiktüte, ich hol sie mir später ab!\"  2. (scherzhaft für): \"Pack mir deine Worte in eine Tüte und schick sie mir per Post!\"  3. Steck dein Gelaber in einen Umschlag und verschick es woanders!  4. Wenn du nicht schweigen kannst, dann sprich deine Worte in ein Sackerl, und ich hol''s mir später ab (sofern ich mir dieses sinnlose Gequatsche von dir später irgendwann tatsächlich noch anhören will)"}]'::jsonb, ''),
  ('wem-von-da-seitn-aureedn', 'wem von da Seitn aureedn', '', '', '', '', 'jemanden von der Seite anreden', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas durch die Hintertür sagen\""}, {"kategorie": "scherzhaft für", "text": "\"jemandem gegenüber nur Andeutungen machen, statt Tacheles zu reden\""}, {"kategorie": "", "text": "jemandem etwas durch die Blume sagen"}, {"kategorie": "", "text": "jemandem etwas nicht direkt ins Gesicht sagen"}]'::jsonb, 'wem von da Seitn kumma'),
  ('wem-von-da-seitn-kumma', 'wem von da Seitn kumma', '', '', '', '', 'jemandem von der Seite kommen', '[{"kategorie": "wörtlich", "text": "\"jemandem durch die Hintertüre kommen\""}, {"kategorie": "scherzhaft für", "text": "\"jemandem gegenüber nur Andeutungen machen, statt Tacheles zu reden\""}, {"kategorie": "", "text": "jemandem etwas durch die Blume sagen"}, {"kategorie": "", "text": "jemandem etwas nicht direkt ins Gesicht sagen"}]'::jsonb, 'wem von da Seitn aureedn'),
  ('reed-mi-ned-gschissn-von-da-seitn-au', 'Reed mi ned gschissn von da Seitn au!', '', '', '', '', 'Rede mich nicht beschissen von der Seite an!', '[{"kategorie": "wörtlich", "text": "\"Komm mir nicht beschissen durch die Hintertüre!\"  2. (scherzhaft für): \"Mach nicht nur Andeutungen, red'' Tacheles mit mir!\"  3. Sag mir nicht alles beschissen durch die Blume!  4. Hör auf, beschissen um den heißen Brei herumzureden!"}]'::jsonb, ''),
  ('ma-soogd-jo-nix-ma-red-jo-nua-davoo', 'Ma soogd jo nix, ma red jo nua davoo!', '', '', '', '', 'Man sagt ja nichts, man redet ja nur davon!', '[{"kategorie": "wörtlich", "text": "\"Man sagt ja nichts, man stellt ja bloß fest!\"  2. (scherzhaft für): \"Reine Info, keine Kritik!\"  3. \"Man redet ja nur, aber keiner muss es gehört haben!\"  4. \"Man sagt ja nichts, man flüstert es bloß mal leise in den Wind!\""}]'::jsonb, ''),
  ('ka-reed', 'Ka Reed!', '', '', '', '', 'Keine Rede!', '[{"kategorie": "wörtlich", "text": "\"Kommt nicht in Frage!\"  2. (scherzhaft für): \"Auf keinen Fall!\"  3. \"Nichts dergleichen!\"  4. \"Keine Chance! \""}]'::jsonb, ''),
  ('do-vaschlogds-ma-de-reed', 'Do vaschlogds ma de Reed!', '', '', '', '', 'Da verschlägt es mir die Rede', '[{"kategorie": "wörtlich", "text": "\"Da verschlägt es mir die Sprache!\"  2. Da fehlen mir die Worte!  3. Da bin ich sprachlos!  4. Da weiß ich nicht, was ich sagen soll!"}]'::jsonb, ''),
  ('a-reengwuam-hod-kaane-aung-owa-ea-schbiads-liachd-mid-da-haut', 'A Reengwuam hod kaane Aung, owa ea schbiads Liachd mid da Haut!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Ein Regenwurm hat keine Augen, aber er spürt das Licht mit der Haut!', '[{"kategorie": "wörtlich", "text": "\"Regenwürmer besitzen keine Augen, nehmen Lichtreize jedoch über ihre Haut wahr!\"  2. Obwohl der Regenwurm keine Augen hat, reagiert er empfindlich auf Licht, das er mit der Haut erkennt!  3. Ein Regenwurm sieht nichts, aber er merkt, wenn es hell wird – mit seiner Haut!"}]'::jsonb, ''),
  ('a-raegiment-kneedln', 'a Rägiment Kneedln', '', '', '', '', 'ein Regiment Knödel', '[{"kategorie": "", "text": "eine Masse Knödel"}]'::jsonb, ''),
  ('jetzd-hod-a-nua-mea-a-oids-reeheidl-zwischn-d-fiass-owahaengan', 'Jetzd hod a nua mea a oids Reeheidl zwischn d''Fiass owahängan!', '', '', '', '', 'Jetzt hat er nur noch ein altes Rehhäutel zwischen den Beinen herunterhängen!', '[{"kategorie": "", "text": "Sein bestes Stück hängt ihm jetzt nur noch als Schlappschwanz zwischen den Beinen herunter!  2. Jetzt hat er nur noch einen schlaffen Schwanz zwischen den Beinen herunterhängen!"}]'::jsonb, ''),
  ('reibgeaschdln-san-gschoeoede-griibane-und-poliade-keana-von-da-geaschdn', 'Reibgeaschdln san gschööde, griibane und poliade Keana von da Geaschdn!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Reibgersteln sind kleine, geschälte, geriebene und polierte Körner von der Gerste!!', '[{"kategorie": "wörtlich", "text": "Reibgersteln sind enthülste, geriebene und geglättete Körner der Gerste!  2. Als Reibgersteln bezeichnet man enthülste, geriebene und polierte Getreidekörner von der Gerste!  3. Bei Reibgersteln handelt es sich um geschälte, geriebene und länglich geschliffene Gerstenkörner!"}]'::jsonb, ''),
  ('roigeaschdln-san-gschoeoede-griibane-und-poliade-keana-von-da-geaschdn', 'Roigeaschdln san gschööde, griibane und poliade Keana von da Geaschdn!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Rollgersteln sind kleine, geschälte, geriebene und polierte Körner von der Gerste!!', '[{"kategorie": "wörtlich", "text": "Rollgersteln sind enthülste, geriebene und geglättete Körner der Gerste!  2. Als Rollgersteln bezeichnet man enthülste, geriebene und polierte Getreidekörner von der Gerste!  3. Bei Rollgersteln handelt es sich um geschälte, geriebene und länglich geschliffene Gerstenkörner!"}]'::jsonb, ''),
  ('geaschdln-san-klaane-runddraade-keana-von-da-geaschdn', 'Geaschdln san klaane, runddraade Keana von da Geaschdn!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Gersteln sind kleine, rundgedrehte Körner von der Gerste!!', '[{"kategorie": "wörtlich", "text": "\"Gersteln sind kleine, rundgeschliffene Körner von der Gerste!\"  2. Als Gersteln bezeichnet man enthülste und polierte Getreidekörner von der Gerste!  3. Bei Gersteln handelt es sich um geschälte und rundgeschliffene Gerstenkörner!"}]'::jsonb, ''),
  ('mit-dem-geaschdl-schau-i-aus-ois-haed-i-aane-aufs-aug-kriagd', 'Mit dem Geaschdl schau I aus, ois häd I aane aufs Aug kriagd!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Mit dem Gerstel schau ich aus, als hätt ich eine aufs Aug gekriegt!', '[{"kategorie": "wörtlich", "text": "\"Mit dem Gerstenkorn seh ich aus, als hätt ich eine aufs Auge bekommen!\"  2. Mit dem Gerstenkorn schau ich aus, als wär ich in eine wilde Schlägerei geraten!  3. Mit dem Augenpickel schau ich aus wie ein Boxer nach der zwölften Runde!"}]'::jsonb, ''),
  ('a-reibgeaschdlsuppn-muassd-kechln-lossn-mit-suppngemuese-und-an-schuss-liabschdeckl', 'A Reibgeaschdlsuppn muassd kechln lossn - mit Suppngemüse und an Schuss Liabschdeckl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Eine Reibgerstelsuppe musst du köcheln lassen – mit Suppengemüse und einem Schuss Liebstöckel!', '[{"kategorie": "wörtlich", "text": "\"Reibgerstelsuppe sollte langsam köcheln – mit Wurzelgemüse und einer Prise Liebstöckel verfeinert!\"  2. Die Reibgerstensuppe braucht Zeit: gutes Suppengemüse, sanftes Köcheln und etwas Liebstöckel – dann entfaltet sie ihr volles Aroma!  3. Lass die Reibgerstensuppe mit Gemüse und Liebstöckel auf kleiner Flamme gemütlich vor sich hinköcheln!"}]'::jsonb, ''),
  ('a-roigeaschdlsuppn-muassd-kechln-lossn-mit-suppngemuese-und-an-schuss-liabschdeckl', 'A Roigeaschdlsuppn muassd kechln lossn - mit Suppngemüse und an Schuss Liabschdeckl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Eine Rollgerstelsuppe musst du köcheln lassen – mit Suppengemüse und einem Schuss Liebstöckel!', '[{"kategorie": "wörtlich", "text": "\"Rollgerstelsuppe sollte langsam köcheln – mit Wurzelgemüse und einer Prise Liebstöckel verfeinert!\"  2. Die Rollgerstensuppe braucht Zeit: gutes Suppengemüse, sanftes Köcheln und etwas Liebstöckel – dann entfaltet sie ihr volles Aroma!  3. Lass die Rollgerstensuppe mit Gemüse und Liebstöckel auf kleiner Flamme gemütlich vor sich hinköcheln!"}]'::jsonb, ''),
