  ('wem-in-da-maungl-haum', 'wem in da Maungl haum', '', '', '', '', 'jemanden in der Mangeln haben', '[{"kategorie": "", "text": "jemanden in der [[Reißen]] haben, jemanden in der [[Baatz]] haben"}, {"kategorie": "", "text": "jemandem hart zusetzen, Druck auf jemanden ausüben, jemanden zermürben, fertigmachen (\"Mangel\" = \"Wäschemangel\" [Gerät aus der Wäschereitechnik, das zum Trocknen und Glätten von Stoffen und Wäsche verwendet wird])"}]'::jsonb, ''),
  ('wem-duach-de-maungl-draan', 'wem duach de Maungl draan', '', '', '', '', 'jemanden durch die Mangel drehen', '[{"kategorie": "", "text": "jemanden arg unter Druck setzen, jemandem so richtig einheizen, [[wem katolisch mochn]]"}, {"kategorie": "", "text": "jemandem ans Leder gehen, mit jemandem Schlitten fahren, [[jemanden]] durch die Faschiermaschine drehen (\"Mangel\" = \"Wäschemangel\" [Gerät aus der Wäschereitechnik, das zum Trocknen und Glätten von Stoffen und Wäsche verwendet wird])"}]'::jsonb, ''),
  ('des-bauxal-reend-schoo', 'Des Bauxal reend schoo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Bauxerl rennt schon!', '[{"kategorie": "wörtlich", "text": "\"Das Kind läuft schon!\"  2. \"Das Kind kann schon alleine laufen!\"  3. \"Das süße Kindchen kann schon ganz selbstständig gehen!\""}]'::jsonb, ''),
  ('ea-reend-wenig-an-jeedn-schaas-zum-dokta', 'Ea reend wenig an jeedn Schaas zum Dokta!', '', '', '', '', 'Er rennt wegen jedem Schas zum Doktor!', '[{"kategorie": "", "text": "Er rennt wegen jedem Wehwehchen zum Arzt!  2. Er rennt wegen jedem Pups zum Arzt!"}]'::jsonb, ''),
  ('wos-reend-denn-do', 'Wos reend denn do?', '', '', '', '', 'Was rennt denn da?', '[{"kategorie": "", "text": "Was läuft denn hier?  2. Was ist denn hier los?  3. Was geht hier vor?"}]'::jsonb, ''),
  ('bei-dem-reends', 'Bei dem reends!', '', '', '', '', 'Bei dem rennt''s!', '[{"kategorie": "", "text": "Bei dem läuft es!  2. Er hat einen Lauf!  3. Es läuft alles rund für ihn!"}]'::jsonb, ''),
  ('de-maschn-reend', 'De Maschn reend!', '', '', '', '', 'Die Masche rennt!', '[{"kategorie": "wörtlich", "text": "Die Laufmasche wird immer länger!  2. Die Masche (Strategie) bewährt sich!"}]'::jsonb, ''),
  ('da-kaas-reend', 'Da Kaas reend!', '', '', '', '', 'Der Käse rennt!', '[{"kategorie": "wörtlich", "text": "Der Käse rinnt!  2. Der Käse läuft!  3. Der Käse gerinnt!"}]'::jsonb, ''),
  ('mia-san-d-brueuen-augrennd', 'Mia san d''Brüün augrennd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mir sind die Brillen angerennt!', '[{"kategorie": "wörtlich", "text": "\"Mir sind die Brillen angelaufen!\"  2. Meine Brille hat sich beschlagen!  3. Meine Gläser haben sich eingedampft!"}]'::jsonb, ''),
  ('dem-rennd-de-oaweid-a-ned-nooch', 'Dem rennd de Oaweid a ned nooch!', '', '', '', '', 'Dem rennt die Arbeit auch nicht nach!', '[{"kategorie": "", "text": "Arbeit ist nicht gerade sein Steckenpferd!  2. Er ist bestimmt alles, nur kein fleißiger Arbeiter!"}]'::jsonb, ''),
  ('dea-muass-wo-augrennd-sei', 'Dea muass wo augrennd sei!', '', '', '', '', 'Der muss wo angerannt sein!', '[{"kategorie": "", "text": "Der muss einen an der Waffel haben!  2. Der kann nicht ganz bei Trost sein!  3. Der tickt wohl nicht ganz richtig im Kopf!"}]'::jsonb, ''),
  ('fia-wem-rennan', 'fia wem rennan', '', '', '', '', 'für jemanden rennen', '[{"kategorie": "", "text": "sich die Füße wundlaufen für jemanden, sich abstrampeln für jemanden"}, {"kategorie": "", "text": "sich für jemanden ins Zeug legen, sich aufreiben für jemanden"}]'::jsonb, ''),
